function formatDate(isoDate) {
  const d = new Date(isoDate);
  return d.toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' });
}

function renderListPage() {
  const postListEl = document.getElementById('postList');
  const postCountEl = document.getElementById('postCount');
  if (!postListEl) return;

  postCountEl.textContent = `共 ${posts.length} 篇`;

  postListEl.innerHTML = posts
    .map((post) => `
      <a class="post-card" href="post.html?id=${post.id}">
        <div class="post-meta">${formatDate(post.date)} · ${post.readTime}</div>
        <h3>${post.title}</h3>
        <p>${post.summary}</p>
      </a>
    `)
    .join('');
}

function enhanceWordContent(container) {
  if (!container || container.dataset.enhancedWord === '1') return;
  container.dataset.enhancedWord = '1';
  container.classList.add('word-clean');

  const normalizeText = (s) =>
    String(s || '')
      .replace(/\u00a0/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

  const escapeHtml = (s) =>
    String(s || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');

  const isMajorTitle = (t) => {
    const s = normalizeText(t);
    return s === '手机取证' || s === 'APK取证' || s === '计算机取证' || s === '移动介质取证' || s === '服务器取证';
  };
  const readQuestionNumber = (t) => {
    const s = normalizeText(t);
    const m = s.match(/^(\d+)\s*[\.．、]\s*(.*)$/);
    return m ? m[1] : '';
  };
  const isQuestionPrompt = (t) => {
    const s = normalizeText(t);
    return /答案格式/.test(s) && (/[?？]/.test(s) || /^(?:\d+\s*[\.．、]\s*)?(?:分析|接上题)/.test(s));
  };
  const isMinorTitle = (t) => !!readQuestionNumber(t) || isQuestionPrompt(t);
  const isQuestionLine = (t) => isQuestionPrompt(t);
  const isAnswerLine = (t) => /^答案[:：]/.test(normalizeText(t));
  const isScriptTitle = (t) => {
    const s = normalizeText(t);
    if (!s) return false;
    if (/输入命令/.test(s)) return true;
    if (/命令[:：]$/.test(s)) return true;
    if (/脚本/.test(s) && (/[:：]$/.test(s) || /ai写的脚本|依旧ai脚本|所用脚本/.test(s))) return true;
    return false;
  };
  const isLikelyCodeLine = (t) => {
    const s = normalizeText(t);
    if (!s) return false;
    if (/^(import|from|def|class|if|elif|else|for|while|try|except|with|return|print)\b/i.test(s)) return true;
    if (/^(?:#!\/|#\s*-\*-\s*coding:|python\s|sqlite3\s|volatility|findstr\b)/i.test(s)) return true;
    if (/^[A-Z0-9_]+\s*=/.test(s)) return true;
    if (/[:,(){}\[\]<>|]|==|!=|>=|<=|=>/.test(s)) return true;
    if (/^\s*[-/]{1,2}[a-z0-9]/i.test(s)) return true;
    if (/\\|\/.+\.\w+/.test(s)) return true;
    if (/\.(py|db|xml|json|txt|so|apk)\b/i.test(s)) return true;
    return false;
  };
  const isStrongCodeLine = (t) => {
    const s = normalizeText(t);
    return /^(?:-f\s+["']|windows\.[a-z]|import\s|from\s|CSV_PATH\s*=|#!\/|Path\(|SELECT\b|with open\(|sqlite3\.|python\s)/i.test(s);
  };
  const isLikelyAnswerLine = (t) => {
    const s = normalizeText(t);
    if (!s) return false;
    if (isAnswerLine(s)) return true;
    if (isScriptTitle(s) || isLikelyCodeLine(s)) return false;
    if (/^(根据|注意|这里|于是|所以|然后|直接|搜索|输入命令|用|在|保险箱|路径|对应|火眼|减去|怕他骗我|脚本前面的注释)/.test(s)) return false;
    if (/[。；;]$/.test(s) && s.length > 10) return false;
    if (s.length <= 72) return true;
    if (/^[A-Za-z0-9@._:\\/\-\s]+$/.test(s)) return true;
    return false;
  };
  const isBoundaryLine = (t) => isMajorTitle(t) || isQuestionLine(t);

  const makeCopyCard = (text, cls = '') => {
    const wrap = document.createElement('div');
    wrap.className = `code-wrap ${cls}`.trim();
    wrap.innerHTML = `<button type="button" class="code-copy-btn">复制</button><pre><code>${escapeHtml(text)}</code></pre>`;
    return wrap;
  };

  const ps = Array.from(container.querySelectorAll('p'));

  let sectionQuestionNo = 0;
  ps.forEach((p) => {
    const t = normalizeText(p.textContent || '');
    if (isMajorTitle(t)) {
      sectionQuestionNo = 0;
      p.classList.add('major-title');
      return;
    }
    if (isQuestionLine(t)) {
      const explicitNo = readQuestionNumber(t);
      sectionQuestionNo = explicitNo ? Number(explicitNo) : sectionQuestionNo + 1;
      p.dataset.questionNum = String(sectionQuestionNo);
      if (!explicitNo) {
        p.dataset.autoQuestionNum = String(sectionQuestionNo);
      }
    }
    if (isMinorTitle(t)) {
      p.classList.add('minor-title');
    }
  });

  for (let i = 0; i < ps.length; i++) {
    const title = normalizeText(ps[i].textContent || '');
    if (!isScriptTitle(title)) continue;

    const lines = [];
    const nodes = [];
    for (let j = i + 1; j < ps.length; j++) {
      const cur = ps[j];
      const txt = normalizeText(cur.textContent || '');
      if (!txt) {
        if (nodes.length) break;
        continue;
      }
      if (isBoundaryLine(txt) || isScriptTitle(txt)) break;
      if (cur.querySelector('img')) {
        if (nodes.length) break;
        continue;
      }
      if (!isLikelyCodeLine(txt) && nodes.length > 0) break;
      if (!isLikelyCodeLine(txt) && nodes.length === 0) continue;
      nodes.push(cur);
      lines.push((cur.textContent || '').replace(/\u00a0/g, ' ').replace(/\s+$/g, ''));
    }
    const codeText = lines.join('\n').trim();
    if (!codeText || !nodes.length) continue;
    ps[i].after(makeCopyCard(codeText, 'answer-copy script-only'));
    nodes.forEach((n) => n.remove());
  }

  for (let i = 0; i < ps.length; i++) {
    const node = ps[i];
    const t = normalizeText(node.textContent || '');
    if (!t || !node.isConnected || !isAnswerLine(t)) continue;
    node.replaceWith(makeCopyCard(t, 'answer-copy answer-only'));
  }

  for (let i = 0; i < ps.length; i++) {
    const q = normalizeText(ps[i].textContent || '');
    if (!isQuestionLine(q)) continue;

    let explicitAnswerFound = false;
    let answerNode = null;
    for (let j = i + 1; j < ps.length; j++) {
      const cur = ps[j];
      const txt = normalizeText(cur.textContent || '');
      if (!txt) continue;
      if (isBoundaryLine(txt) || isScriptTitle(txt)) break;
      if (!cur.isConnected || cur.querySelector('img')) continue;
      if (isAnswerLine(txt)) {
        explicitAnswerFound = true;
        break;
      }
      if (!answerNode && isLikelyAnswerLine(txt)) {
        answerNode = cur;
      }
    }
    if (!explicitAnswerFound && answerNode && answerNode.isConnected) {
      answerNode.replaceWith(makeCopyCard(normalizeText(answerNode.textContent || ''), 'answer-copy answer-only'));
    }
  }

  const refreshedPs = Array.from(container.querySelectorAll('p'));
  for (let i = 0; i < refreshedPs.length; i++) {
    const curP = refreshedPs[i];
    const t = normalizeText(curP.textContent || '');
    if (!t || !isLikelyCodeLine(t)) continue;
    if (curP.previousElementSibling && curP.previousElementSibling.classList?.contains('code-wrap')) continue;

    const lines = [];
    const nodes = [];
    for (let j = i; j < refreshedPs.length; j++) {
      const cur = refreshedPs[j];
      const txt = normalizeText(cur.textContent || '');
      if (!txt) continue;
      if (cur.querySelector('img')) break;
      if (isBoundaryLine(txt) || isScriptTitle(txt) || isAnswerLine(txt)) break;
      if (!isLikelyCodeLine(txt) && lines.length > 0 && !/^\s/.test(cur.textContent || '')) break;
      nodes.push(cur);
      lines.push((cur.textContent || '').replace(/\u00a0/g, ' ').replace(/\s+$/g, ''));
    }
    if (nodes.length < 2 && !isStrongCodeLine(t)) continue;
    const codeText = lines.join('\n').trim();
    if (!codeText) continue;
    nodes[0].before(makeCopyCard(codeText, 'answer-copy script-only'));
    nodes.forEach((n) => n.remove());
  }
}

function buildQuestionToc(detailEl) {
  if (!detailEl) return;
  const mainEl = detailEl.closest('.detail-main');
  const contentEl = detailEl.querySelector('.content');
  if (!mainEl || !contentEl) return;

  const normalizeText = (s) =>
    String(s || '')
      .replace(/\u00a0/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

  const escapeHtml = (s) =>
    String(s || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');

  const isMajorTitle = (s) => ['手机取证', 'APK取证', '计算机取证', '移动介质取证', '服务器取证'].includes(normalizeText(s));

  const nodes = Array.from(contentEl.querySelectorAll('p, h3'));
  const items = [];
  let currentSectionId = '';
  let sectionQuestionNo = 0;

  nodes.forEach((node, idx) => {
    const raw = normalizeText(node.textContent || '');
    if (!raw) return;

    if (isMajorTitle(raw)) {
      sectionQuestionNo = 0;
      if (!node.id) node.id = `sec-${idx + 1}`;
      currentSectionId = node.id;
      items.push({ type: 'section', id: node.id, label: raw });
      node.classList.add('question-anchor');
      return;
    }

    const dataNum = node.dataset.questionNum || node.dataset.autoQuestionNum;
    const isQuestionNode = !!dataNum || (/答案格式/.test(raw) && (/[?？]/.test(raw) || /^(?:\d+\s*[\.．、]\s*)?(?:分析|接上题)/.test(raw)));
    if (!isQuestionNode) return;
    const m = raw.match(/^(\d+)\s*[\.．、]?\s*(.*)$/);
    const num = dataNum || (m ? m[1] : String(++sectionQuestionNo));
    if (!dataNum && m) sectionQuestionNo = Number(m[1]);
    let label = m ? m[2] : raw;
    label = label.replace(/[\[［]答案格式[\s\S]*$/, '').trim();
    if (!label) label = `第 ${num} 题`;
    if (!node.id) node.id = `q-${num}-${idx + 1}`;
    node.classList.add('question-anchor');
    items.push({
      type: 'question',
      id: node.id,
      num,
      label: label.length > 26 ? `${label.slice(0, 26)}...` : label,
      sectionId: currentSectionId
    });
  });

  let tocEl = document.getElementById('postToc');
  if (!tocEl) {
    tocEl = document.createElement('aside');
    tocEl.id = 'postToc';
    tocEl.className = 'post-toc';
    tocEl.innerHTML = `
      <div class="post-toc-head">题目目录</div>
      <nav class="post-toc-list" aria-label="题目目录"></nav>
    `;
    mainEl.appendChild(tocEl);
  }

  if (!items.length) {
    tocEl.style.display = 'none';
    mainEl.classList.remove('detail-main-with-toc');
    return;
  }

  mainEl.classList.add('detail-main-with-toc');
  tocEl.style.display = '';
  const listEl = tocEl.querySelector('.post-toc-list');
  listEl.innerHTML = items.map((it) => {
    if (it.type === 'section') {
      return `<a class="toc-section" href="#${escapeHtml(it.id)}" data-target="${escapeHtml(it.id)}">${escapeHtml(it.label)}</a>`;
    }
    return `<a class="toc-question" href="#${escapeHtml(it.id)}" data-target="${escapeHtml(it.id)}">${escapeHtml(it.num)}. ${escapeHtml(it.label)}</a>`;
  }).join('');

  listEl.querySelectorAll('a[data-target]').forEach((a) => {
    a.addEventListener('click', (e) => {
      e.preventDefault();
      const target = document.getElementById(a.dataset.target || '');
      if (!target) return;
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      history.replaceState(null, '', `#${target.id}`);
    });
  });
}

function bindCopyButtons(root) {
  if (!root) return;
  root.querySelectorAll('.code-copy-btn').forEach((btn) => {
    if (btn.dataset.boundCopy === '1') return;
    btn.dataset.boundCopy = '1';
    btn.addEventListener('click', async () => {
      const codeEl = btn.parentElement?.querySelector('code');
      if (!codeEl) return;
      const text = codeEl.textContent || '';
      const done = () => {
        const prev = btn.textContent;
        btn.textContent = '已复制';
        setTimeout(() => {
          btn.textContent = prev;
        }, 1200);
      };
      try {
        await navigator.clipboard.writeText(text);
        done();
      } catch {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.left = '-9999px';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        ta.remove();
        done();
      }
    });
  });
}

function setupImagePreview(root) {
  if (!root || !document.body) return;

  let lightbox = document.getElementById('imgLightbox');
  let lightboxImg = document.getElementById('imgLightboxImg');
  if (!lightbox) {
    lightbox = document.createElement('div');
    lightbox.id = 'imgLightbox';
    lightbox.className = 'img-lightbox';
    lightbox.hidden = true;
    lightbox.innerHTML = `
      <button type="button" class="img-lightbox-close" aria-label="关闭预览">关闭</button>
      <img id="imgLightboxImg" alt="preview">
    `;
    document.body.appendChild(lightbox);
    lightboxImg = lightbox.querySelector('#imgLightboxImg');
    lightbox.addEventListener('click', (e) => {
      const target = e.target;
      if (target === lightbox || (target instanceof HTMLElement && target.classList.contains('img-lightbox-close'))) {
        lightbox.hidden = true;
        document.body.style.overflow = '';
      }
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        lightbox.hidden = true;
        document.body.style.overflow = '';
      }
    });
  } else if (!lightboxImg) {
    lightboxImg = lightbox.querySelector('#imgLightboxImg');
  }

  root.querySelectorAll('img').forEach((img) => {
    if (img.dataset.zoomBound === '1') return;
    img.dataset.zoomBound = '1';
    img.dataset.zoomable = '1';
    img.addEventListener('click', () => {
      if (!lightboxImg) return;
      lightboxImg.src = img.currentSrc || img.src;
      lightboxImg.alt = img.alt || 'preview';
      lightbox.hidden = false;
      document.body.style.overflow = 'hidden';
    });
  });
}

async function renderDetailPage() {
  const detailEl = document.getElementById('postDetail');
  if (!detailEl) return;

  const params = new URLSearchParams(window.location.search);
  const id = params.get('id');
  const post = posts.find((item) => item.id === id);

  if (!post) {
    detailEl.innerHTML = '<p>文章不存在，请返回首页查看。</p>';
    return;
  }

  let contentHtml = '';
  if (post.contentType === 'html-file') {
    try {
      const resp = await fetch(post.content, { cache: 'no-store' });
      if (!resp.ok) throw new Error('fetch failed');
      contentHtml = await resp.text();
    } catch {
      detailEl.innerHTML = '<p>文章加载失败，请检查文章资源是否完整。</p>';
      return;
    }
  } else {
    contentHtml = String(post.content || '')
      .split('\n\n')
      .map((paragraph) => `<p>${paragraph}</p>`)
      .join('');
  }

  if (post.id === '1') {
    contentHtml = POST1_PREFACE_HTML + contentHtml;
  }

  detailEl.innerHTML = `
    <h1>${post.title}</h1>
    <div class="meta">${formatDate(post.date)} · ${post.readTime}</div>
    <div class="content">${contentHtml}</div>
  `;

  const contentEl = detailEl.querySelector('.content');
  enhanceWordContent(contentEl);
  bindCopyButtons(detailEl);
  setupImagePreview(contentEl);
  buildQuestionToc(detailEl);
}

function renderYear() {
  const y = document.getElementById('year');
  if (y) y.textContent = new Date().getFullYear();
}

function setupAvatarAndFavicon() {
  const candidates = ['avatar.jpg', 'images/avatar.jpg', './avatar.jpg', './images/avatar.jpg'];
  const faviconEl = document.getElementById('appFavicon');
  const aboutAvatar = document.getElementById('aboutAvatar');

  const test = (url) =>
    new Promise((resolve) => {
      const img = new Image();
      img.onload = () => resolve(true);
      img.onerror = () => resolve(false);
      img.src = url;
    });

  (async () => {
    for (const url of candidates) {
      const ok = await test(url);
      if (!ok) continue;
      if (faviconEl) faviconEl.href = url;
      if (aboutAvatar) aboutAvatar.src = url;
      return;
    }
    // Hard fallback: use embedded avatar so server file layout does not matter.
    if (faviconEl) faviconEl.href = INLINE_AVATAR_DATA_URL;
    if (aboutAvatar) aboutAvatar.src = INLINE_AVATAR_DATA_URL;
  })();
}

function trySetBackgroundImage() {
  const candidates = [
    'gosick-bg.jpg',
    'images/gosick-bg.jpg',
    './images/gosick-bg.jpg',
    '../images/gosick-bg.jpg',
    './gosick-bg.jpg',
    '../gosick-bg.jpg'
  ];

  const test = (url) =>
    new Promise((resolve) => {
      const img = new Image();
      img.onload = () => resolve(true);
      img.onerror = () => resolve(false);
      img.src = url;
    });

  (async () => {
    for (const url of candidates) {
      const ok = await test(url);
      if (ok) {
        document.body.style.setProperty('--bg-image-url', `url("${url}")`);
        return;
      }
    }
  })();
}

function setupClock() {
  const clockEl = document.getElementById('clock');
  if (!clockEl) return;

  const tick = () => {
    const now = new Date();
    const text = now.toLocaleString('zh-CN', {
      hour12: false,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
    clockEl.textContent = text;
  };

  tick();
  setInterval(tick, 1000);
}

function setupMusicAndViz() {
  const audio = document.getElementById('bgm');
  const toggleBtn = document.getElementById('musicToggle');
  const canvas = document.getElementById('audioViz');
  if (!audio || !toggleBtn || !canvas) return;

  const audioCandidates = [
    'bgm.mp3',
    'assets/bgm.mp3',
    './assets/bgm.mp3',
    '../assets/bgm.mp3',
    './bgm.mp3',
    '../bgm.mp3'
  ];
  const KEY_TIME = 'blog_bgm_current_time';
  const KEY_PAUSED = 'blog_bgm_paused';

  audio.volume = 0.35;

  const savedTime = Number(localStorage.getItem(KEY_TIME));
  const savedPausedRaw = localStorage.getItem(KEY_PAUSED);
  const shouldStartPaused = savedPausedRaw == null ? true : savedPausedRaw !== 'false';

  const updateBtn = () => {
    toggleBtn.classList.toggle('muted', audio.paused);
    toggleBtn.setAttribute('aria-label', audio.paused ? '开启音乐' : '关闭音乐');
    toggleBtn.setAttribute('title', audio.paused ? '开启音乐' : '关闭音乐');
  };

  const saveState = () => {
    localStorage.setItem(KEY_TIME, String(audio.currentTime || 0));
    localStorage.setItem(KEY_PAUSED, String(audio.paused));
  };

  toggleBtn.addEventListener('click', async () => {
    if (audio.paused) {
      try {
        await audio.play();
      } catch {
        toggleBtn.classList.add('muted');
        return;
      }
    } else {
      audio.pause();
    }
    saveState();
    updateBtn();
  });

  audio.addEventListener('play', () => {
    saveState();
    updateBtn();
  });
  audio.addEventListener('pause', () => {
    saveState();
    updateBtn();
  });
  audio.addEventListener('timeupdate', saveState);
  audio.addEventListener('error', () => {
    toggleBtn.classList.add('muted');
    toggleBtn.setAttribute('title', '音频加载失败');
  });

  window.addEventListener('beforeunload', saveState);

  const testAudioUrl = (url) =>
    new Promise((resolve) => {
      const probe = document.createElement('audio');
      probe.preload = 'metadata';
      probe.src = url;
      probe.onloadedmetadata = () => resolve(true);
      probe.onerror = () => resolve(false);
    });

  const ensureAudioSrc = async () => {
    for (const url of audioCandidates) {
      const ok = await testAudioUrl(url);
      if (ok) {
        audio.src = url;
        audio.load();
        if (!Number.isNaN(savedTime) && savedTime > 0) {
          audio.currentTime = savedTime;
        }
        return true;
      }
    }
    return false;
  };

  const ctx = canvas.getContext('2d');
  const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  const analyser = audioCtx.createAnalyser();
  analyser.fftSize = 512;
  analyser.smoothingTimeConstant = 0.82;
  const bufferLength = analyser.frequencyBinCount;
  const dataArray = new Uint8Array(bufferLength);
  const source = audioCtx.createMediaElementSource(audio);
  source.connect(analyser);
  analyser.connect(audioCtx.destination);

  const draw = () => {
    requestAnimationFrame(draw);
    analyser.getByteFrequencyData(dataArray);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const bars = 92;
    const barWidth = canvas.width / bars;
    for (let i = 0; i < bars; i++) {
      const t = i / (bars - 1);
      const logIndex = Math.floor((Math.pow(2, t * 8) - 1) / (Math.pow(2, 8) - 1) * (bufferLength - 1));
      const highBoost = 0.82 + t * 0.42;
      const v = Math.min(1, (dataArray[logIndex] / 255) * highBoost);
      const ambient = 0.35 + Math.sin((performance.now() / 260) + i * 0.22) * 0.2;
      const maxHalfHeight = canvas.height * 0.42;
      const h = Math.max(1, v * maxHalfHeight);
      const x = i * barWidth;
      const midY = canvas.height / 2;
      const glow = Math.max(0.2, v);
      const topY = Math.max(0, midY - h - ambient);
      const segH = h + ambient;

      ctx.fillStyle = `rgba(255, 255, 255, ${0.14 + glow * 0.18})`;
      ctx.fillRect(x + 0.25, topY, Math.max(0.8, barWidth - 0.5), segH);
      ctx.fillStyle = `rgba(255, 255, 255, ${0.14 + glow * 0.18})`;
      ctx.fillRect(x + 0.25, midY, Math.max(0.8, barWidth - 0.5), segH);
    }
  };
  draw();

  const tryStart = async () => {
    const srcReady = await ensureAudioSrc();
    if (!srcReady) {
      toggleBtn.classList.add('muted');
      toggleBtn.setAttribute('title', '音频文件未找到');
      return;
    }

    if (shouldStartPaused) {
      audio.pause();
      updateBtn();
      saveState();
      return;
    }

    if (audioCtx.state === 'suspended') {
      await audioCtx.resume();
    }

    try {
      await audio.play();
      updateBtn();
    } catch {
      toggleBtn.classList.add('muted');
    }
  };

  document.addEventListener('click', () => {
    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }
  }, { once: true });

  updateBtn();
  tryStart();
}

async function setupLive2D() {
  const host = document.getElementById('live2dPet');
  if (!host) return;

  if (typeof window.__blogLive2DDestroy === 'function') {
    try {
      window.__blogLive2DDestroy();
    } catch {}
  }

  const encodePath = (p) => p.split('/').map(encodeURIComponent).join('/');
  const sourceDir = './pet/huaqun';
  const sourceModel = '花裙拆分.model3.json';
  const modelUrl = new URL(encodePath(`${sourceDir}/${sourceModel}`), window.location.href).toString();

  const loadScript = (url) => new Promise((resolve, reject) => {
    const existing = document.querySelector(`script[data-live2d-src="${url}"]`);
    if (existing) {
      if (existing.dataset.loaded === '1') {
        resolve();
        return;
      }
      existing.addEventListener('load', () => resolve(), { once: true });
      existing.addEventListener('error', () => reject(new Error(`script load failed: ${url}`)), { once: true });
      return;
    }

    const script = document.createElement('script');
    script.src = url;
    script.async = true;
    script.dataset.live2dSrc = url;
    script.onload = () => {
      script.dataset.loaded = '1';
      resolve();
    };
    script.onerror = () => reject(new Error(`script load failed: ${url}`));
    document.head.appendChild(script);
  });

  const ensureOML2D = async () => {
    if (window.OML2D?.loadOml2d) return window.OML2D;

    const urls = [
      './_oml2d.min.js',
      'https://cdn.jsdelivr.net/npm/oh-my-live2d@0.19.3/dist/index.min.js',
      'https://unpkg.com/oh-my-live2d@0.19.3/dist/index.min.js'
    ];

    let lastError;
    for (const url of urls) {
      try {
        await loadScript(url);
        if (window.OML2D?.loadOml2d) return window.OML2D;
      } catch (error) {
        lastError = error;
      }
    }

    throw lastError || new Error('OML2D runtime unavailable');
  };

  host.dataset.live2dError = '';
  host.style.display = 'block';
  host.style.pointerEvents = 'none';
  host.replaceChildren();

  try {
    const resp = await fetch(modelUrl, { cache: 'no-store' });
    if (!resp.ok) {
      throw new Error(`model json fetch failed: ${resp.status}`);
    }

    const oml2d = await ensureOML2D();

    const getHostBox = () => ({
      width: Math.max(1, host.clientWidth || 300),
      height: Math.max(1, host.clientHeight || 460)
    });

    const styleStage = () => {
      const stage = host.querySelector('#oml2d-stage');
      if (!stage) return;
      Object.assign(stage.style, {
        position: 'absolute',
        inset: '0',
        left: '0',
        right: '0',
        top: '0',
        bottom: '0',
        width: '100%',
        height: '100%',
        overflow: 'hidden',
        background: 'transparent',
        pointerEvents: 'none',
        animation: 'none',
        transform: 'none'
      });

      const canvas = stage.querySelector('#oml2d-canvas');
      if (canvas) {
        Object.assign(canvas.style, {
          position: 'absolute',
          inset: '0',
          width: '100%',
          height: '100%',
          pointerEvents: 'none',
          background: 'transparent'
        });
      }
    };

    let destroyed = false;
    let resizeObserver = null;
    let resizeTimer = 0;
    let pet = null;

    const cleanup = () => {
      if (destroyed) return;
      destroyed = true;
      window.removeEventListener('resize', queueLayout);
      window.removeEventListener('pagehide', cleanup);
      if (resizeObserver) resizeObserver.disconnect();
      if (resizeTimer) window.clearTimeout(resizeTimer);
      if (host.isConnected) {
        host.replaceChildren();
      }
      delete window.__blogLive2D;
    };

    const applyLayout = () => {
      if (destroyed) return;

      styleStage();
      const model = pet?.models?.model;
      if (!model?.internalModel) return;
      const rawWidth = Number(model.internalModel.width) || 0;
      const rawHeight = Number(model.internalModel.height) || 0;
      if (rawWidth <= 0 || rawHeight <= 0) {
        window.setTimeout(queueLayout, 80);
        return;
      }

      const box = getHostBox();
      const insetX = window.innerWidth <= 640 ? 4 : 8;
      const insetY = window.innerWidth <= 640 ? 2 : 4;
      const maxWidth = Math.max(1, box.width - insetX * 2);
      const maxHeight = Math.max(1, box.height - insetY * 2);
      const fitScale = Math.max(0.01, Math.min(maxWidth / rawWidth, maxHeight / rawHeight));
      const zoom = window.innerWidth <= 640 ? 1.34 : 1.46;
      const scale = fitScale * zoom;
      const offsetY = rawHeight * scale * (window.innerWidth <= 640 ? 0.5 : 0.46);
      const offsetX = box.width * (window.innerWidth <= 640 ? 0.03 : 0.05);

      model.anchor.set(1, 1);
      model.rotation = 0;
      model.interactive = false;
      model.scale.set(scale);
      model.x = box.width - insetX + offsetX;
      model.y = box.height - insetY + offsetY;
    };

    const queueLayout = () => {
      if (destroyed) return;
      if (resizeTimer) window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(applyLayout, 16);
    };

    window.__blogLive2DDestroy = cleanup;

    pet = oml2d.loadOml2d({
      sayHello: false,
      dockedPosition: 'right',
      primaryColor: 'rgba(0,0,0,0)',
      mobileDisplay: true,
      parentElement: host,
      transitionTime: 0,
      statusBar: {
        disable: true
      },
      tips: {
        style: { display: 'none' },
        mobileStyle: { display: 'none' },
        idleTips: { message: [], duration: 0, interval: 600000, priority: 0 },
        welcomeTips: { message: {}, duration: 0, priority: 0 },
        copyTips: { message: [], duration: 0, priority: 0 }
      },
      menus: {
        disable: true
      },
      stageStyle: {
        width: '100%',
        height: '100%',
        right: '0px',
        bottom: '0px',
        left: '0px',
        top: '0px',
        position: 'absolute',
        zIndex: 1,
        background: 'transparent',
        transform: 'none'
      },
      models: [
        {
          path: modelUrl,
          scale: 0.01,
          position: [0, 0],
          mobileScale: 0.01,
          mobilePosition: [0, 0],
          anchor: [0, 0],
          stageStyle: {
            width: '100%',
            height: '100%',
            right: '0px',
            bottom: '0px',
            left: '0px',
            top: '0px',
            position: 'absolute',
            transform: 'none'
          },
          mobileStageStyle: {
            width: '100%',
            height: '100%',
            right: '0px',
            bottom: '0px',
            left: '0px',
            top: '0px',
            position: 'absolute',
            transform: 'none'
          }
        }
      ]
    });

    const waitForModelReady = () => {
      if (destroyed) return;
      const model = pet?.models?.model;
      if (model?.internalModel) {
        queueLayout();
        window.setTimeout(queueLayout, 120);
        window.setTimeout(queueLayout, 600);
        return;
      }
      if (model && typeof model.once === 'function') {
        model.once('load', () => {
          queueLayout();
          window.setTimeout(queueLayout, 120);
          window.setTimeout(queueLayout, 600);
        });
        return;
      }
      window.setTimeout(waitForModelReady, 50);
    };

    if ('ResizeObserver' in window) {
      resizeObserver = new ResizeObserver(() => queueLayout());
      resizeObserver.observe(host);
    }

    window.addEventListener('resize', queueLayout);
    window.addEventListener('pagehide', cleanup, { once: true });

    waitForModelReady();
    queueLayout();
    window.setTimeout(queueLayout, 120);
    window.setTimeout(queueLayout, 600);
    window.setTimeout(queueLayout, 1400);
    window.__blogLive2D = pet;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    host.dataset.live2dError = message;
    console.error('Live2D model load failed:', error);
  }
}

renderListPage();
renderDetailPage();
renderYear();
setupAvatarAndFavicon();
trySetBackgroundImage();
setupClock();
setupMusicAndViz();
setupLive2D();

